const tabId = 118779795;
const listings = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/vehicledetail/"]'));
  const seen = new Set();
  const results = [];
  for (const a of links) {
    const cleanHref = a.href.split('?')[0];
    if (seen.has(cleanHref)) continue;
    seen.add(cleanHref);

    // Find card container
    let container = a.closest('.vehicle-card') || a.closest('div[class*="vehicle"]') || a.parentElement;
    while (container && !container.innerText.includes('$') && container.parentElement) {
      container = container.parentElement;
    }

    results.push({
      href: a.href,
      cleanHref,
      text: a.textContent.trim(),
      cardText: container ? container.innerText.slice(0, 400) : ''
    });
  }
  return results;
});
console.log('Total listings found:', listings.length);
