const tabId = 118779795;
const formHandlers = await browserjs(tabId, () => {
  const form = document.querySelector('cars-search-form');
  const sr = form.shadowRoot;
  const makeSelect = sr.querySelector('fuse-select[name="makes[]"]');
  const innerSelect = makeSelect.shadowRoot.querySelector('select');

  // Dispatch change on innerSelect and makeSelect
  innerSelect.value = 'bmw';
  innerSelect.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  makeSelect.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true, detail: { value: 'bmw' } }));
  makeSelect.dispatchEvent(new CustomEvent('fuse-change', { bubbles: true, composed: true, detail: { value: 'bmw' } }));

  return {
    makeValue: makeSelect.value,
    innerValue: innerSelect.value
  };
});
console.log(formHandlers);

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

// Now let's check what models are available
const models = await browserjs(tabId, () => {
  const form = document.querySelector('cars-search-form').shadowRoot;
  const modelSelect = form.querySelector('fuse-select[name="models[]"]');
  const inner = modelSelect?.shadowRoot?.querySelector('select') || modelSelect;
  return Array.from(inner.querySelectorAll('option')).map(o => ({ value: o.value, text: o.text }));
});
console.log('Models count:', models.length, models.slice(0, 15));

