const tabId = 118779795;
const result = await browserjs(tabId, () => {
  const form = document.querySelector('cars-search-form').shadowRoot;

  // stock_type: used
  const stockSelect = form.querySelector('fuse-select[name="stock_type"]');
  const innerStock = stockSelect.shadowRoot.querySelector('select');
  innerStock.value = 'used';
  innerStock.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  stockSelect.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true, detail: { value: 'used' } }));

  // makes[]: bmw
  const makeSelect = form.querySelector('fuse-select[name="makes[]"]');
  const innerMake = makeSelect.shadowRoot.querySelector('select');
  innerMake.value = 'bmw';
  innerMake.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  makeSelect.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true, detail: { value: 'bmw' } }));

  // models[]: bmw-135
  const modelSelect = form.querySelector('fuse-select[name="models[]"]');
  const innerModel = modelSelect.shadowRoot.querySelector('select');
  innerModel.value = 'bmw-135';
  innerModel.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  modelSelect.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true, detail: { value: 'bmw-135' } }));

  // maximum_distance: all
  const distSelect = form.querySelector('fuse-select[name="maximum_distance"]');
  const innerDist = distSelect.shadowRoot.querySelector('select');
  innerDist.value = 'all';
  innerDist.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  distSelect.dispatchEvent(new CustomEvent('change', { bubbles: true, composed: true, detail: { value: 'all' } }));

  return {
    stock: innerStock.value,
    make: innerMake.value,
    model: innerModel.value,
    dist: innerDist.value
  };
});

console.log(result);

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

const submitInfo = await browserjs(tabId, () => {
  const form = document.querySelector('cars-search-form').shadowRoot;
  const btn = form.querySelector('fuse-button[type="submit"], button[type="submit"]');
  return {
    btnText: btn?.textContent?.trim()
  };
});
console.log(submitInfo);

