const targetUrl = "https://www.cars.com/vehicledetail/0d198339-0653-4df5-a69b-29c3c12ccf38/";
await tool.navigate({ tabId, url: targetUrl });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 8000 });

// Extract full details from the page
const fullDetails = await browserjs(tabId, () => {
  const sellerNotesEl = document.getElementById('sellers-notes');
  const sellerInfoEl = document.getElementById('dealers-info');

  // Also get contact seller section
  const contactSellerEl = document.getElementById('contact-seller') || document.querySelector('.contact-seller');

  // Get all text under seller notes
  const notesText = sellerNotesEl ? sellerNotesEl.innerText : 'Not found';

  // Get all text under seller info
  const infoText = sellerInfoEl ? sellerInfoEl.innerText : 'Not found';

  // Vehicle header
  const title = document.querySelector('h1')?.innerText;
  const price = document.querySelector('.primary-price')?.innerText;
  const vinStock = document.querySelector('.features-and-specs')?.innerText?.split('\n')[1];

  return {
    title,
    price,
    vinStock,
    notesText,
    infoText,
    contactText: contactSellerEl?.innerText
  };
});

console.log(JSON.stringify(fullDetails, null, 2));
"}

